head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setGridSize]<br/>GridView 컴포넌트의 너비(Width)와 높이(Height)를 설정합니다.",
    "validation" : [
        "height(필수) 파라미터로 GridView 컴포넌트의 높이(Height)를 픽셀(px)로 설정합니다.",
        "setGridSize() 실행 시 initFixedHeightByRowNum 속성은 무시되고 GridView 의 높이가 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 정적 select1 초기 선택값 세팅 (selectedIndex 초기 미적용 대응)
    par_width.setValue("900");
    par_height.setValue("500");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - initFixedHeightByRowNum="5" + visibleRowNum="5" 로 초기 높이를 5행 기준으로 고정 (@spec 무시 검증 전제)
//  - setGridSize 실행 시 고정된 초기 높이와 무관하게 height 파라미터로 높이가 변경됨을 검증
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (col1~col6, 15행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 그리드는 initFixedHeightByRowNum=5 (+ visibleRowNum=5) 로 초기 높이가 5행 기준으로 고정됨\n[절차] par_height 선택(초기 고정높이보다 크게/작게) 후 (setGridSize) 클릭\n[확인] setGridSize(width, height) 실행 시 initFixedHeightByRowNum(5행 고정) 을 무시하고 그리드 offsetHeight 가 설정 height px 로 변경 (확대/축소 모두)"', '', 'label1');

    // target 생성 (6컬럼 × 200px, initFixedHeightByRowNum=5, visibleRowNum=5)
    await scwin.createGridView();
}



// 그리드 데이터 (15행)
scwin.fillData = function () {
    let rows = [];
    for (var i = 1; i <= 15; i++) {
        rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i, col5: "E" + i, col6: "F" + i });
    }
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (initFixedHeightByRowNum=5 로 초기 높이 5행 고정)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" initFixedHeightByRowNum="5" style="width:400px;height:280px;">';
    s += '<w2:caption style="" id="caption1" value="setGridSize 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="200" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column5" value="col5"></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="column6" value="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="200" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col5" value=""></w2:column>';
    s += '<w2:column width="200" style="" inputType="text" id="col6" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// setGridSize 호출 : par_width / par_height 의 값을 그리드에 설정 후 적용값 확인
//  - initFixedHeightByRowNum=5 로 초기 높이가 고정된 상태에서 setGridSize(W,H) 실행
//  - 초기 고정높이보다 크게(확대)/작게(축소) 모두 height 파라미터로 offsetHeight 가 변경됨을 실측 (initFixedHeightByRowNum 무시)
scwin.btn_setGridSize_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let vWidth = parseInt(par_width.getValue(), 10);
    let vHeight = parseInt(par_height.getValue(), 10);

    // 실행 전 그리드 크기 (initFixedHeightByRowNum=5 기준 초기 고정 높이)
    let beforeEl = document.querySelector("[id$='target1']");
    let beforeH = beforeEl ? beforeEl.offsetHeight : 0;

    // 메소드 실행
    target1.setGridSize(vWidth, vHeight);

    setTimeout(function () {
        let afterEl = document.querySelector("[id$='target1']");
        let afterW = afterEl ? afterEl.offsetWidth : 0;
        let afterH = afterEl ? afterEl.offsetHeight : 0;

        let dir = (vHeight >= beforeH) ? "확대 시도" : "축소 시도";
        let note = (afterH === vHeight)
            ? "설정 height 반영됨 (initFixedHeightByRowNum=5 무시하고 높이 변경)"
            : "설정 height 미반영 -> 초기 고정높이(" + beforeH + "px)로 복귀";
        bottom.setReturnValue("[결과] 설정값 width=" + vWidth + "px, height=" + vHeight + "px (" + dir + ") -> 실행 전 offsetHeight=" + beforeH + "px(initFixedHeightByRowNum=5 기준 5행 고정) -> 실행 후 offsetWidth=" + afterW + "px, offsetHeight=" + afterH + "px | " + note);
    }, 300);
}
